// Icônes couleur (Microsoft Fluent Emoji, Flat Color Icons ; données dans IKONEN à la fin de ce fichier) : mêmes noms que les icônes Ant Design remplacées,
// donc toute l'application les utilise sans autre changement. Les identifiants des dégradés sont rendus uniques
// (sinon une icône cachée, par ex. dans un onglet fermé, ferait disparaître les couleurs des autres).
function farbig(name) {
  const K = React.forwardRef(({ className, style, onClick, spin, rotate, twoToneColor, ...rest }, ref) => {
    const d = IKONEN[name];
    const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
    const html = React.useMemo(() => d.b.replace(/id="([^"]+)"/g, `id="$1${uid}"`).replace(/url\(#([^)]+)\)/g, `url(#$1${uid})`)
      .replace(/href="#([^"]+)"/g, `href="#$1${uid}"`), [uid]);
    return (
      <span ref={ref} role="img" aria-hidden="true" className={`anticon farb-icon farb-${name}${className ? ` ${className}` : ""}`} style={style} onClick={onClick} {...rest}>
        <svg viewBox={`0 0 ${d.w} ${d.h}`} width="1em" height="1em" focusable="false" dangerouslySetInnerHTML={{ __html: html }} />
      </span>
    );
  });
  K.displayName = `Icon_${name}`;
  return K;
}
