const iconStilLesen = () => { try { return localStorage.getItem("mrs-icons") || "grau"; } catch { return "grau"; } };
const iconStilSetzen = (v) => { try { localStorage.setItem("mrs-icons", v); } catch { /* sans stockage */ } document.body.classList.toggle("icons-grau", v === "grau"); };
iconStilSetzen(iconStilLesen());
(() => {
  const kopf = (tag, attr) => { const e = document.createElement(tag); Object.assign(e, attr); document.head.appendChild(e); };
  if (!document.querySelector('link[rel="manifest"]')) kopf("link", { rel: "manifest", href: "/manifest.webmanifest" });
  kopf("link", { rel: "apple-touch-icon", href: "/apple-touch-icon.png" });
  kopf("meta", { name: "theme-color", content: "#14212B" });
  kopf("meta", { name: "apple-mobile-web-app-capable", content: "yes" });
  if ("serviceWorker" in navigator && isSecureContext) addEventListener("load", () => navigator.serviceWorker.register("/sw.js").catch(() => {}));
})();

ReactDOM.createRoot(document.getElementById("root")).render(<React.StrictMode><Root /></React.StrictMode>);